-- Fix Medina Book 1 lesson 1 rules against the Arabic sharh.
-- Scope: only lesson 1 of Мединский курс (Том 1).

begin;

delete from public.rule_sections
where rule_id in (
  select id
  from public.rules
  where course_name = 'Мединский курс (Том 1)'
    and lesson_number = '1'
);

delete from public.rules
where course_name = 'Мединский курс (Том 1)'
  and lesson_number = '1';

insert into public.rules (course_name, lesson_number, title, content, sort_order, rule_kind, summary) values
(
  'Мединский курс (Том 1)',
  '1',
  'هٰذَا (это/этот: указательное имя для близкого мужского рода)',
  $$<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">هٰذَا</span><p class="rule-study-text"><span dir="rtl" lang="ar">هٰذَا</span> — <span dir="rtl" lang="ar">اِسْمُ إِشَارَةٍ</span>, указательное имя для одного близкого предмета или лица мужского рода: разумного и неразумного.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">هٰذَا</span><span class="rule-term-ru">это / этот</span></div><div class="rule-meaning-card rule-term-structure"><span class="rule-term-ar" dir="rtl" lang="ar">اِسْمُ إِشَارَةٍ</span><span class="rule-term-ru">указательное имя</span></div><div class="rule-meaning-card rule-term-subject"><span class="rule-term-ar" dir="rtl" lang="ar">الْعَاقِلُ</span><span class="rule-term-ru">разумный: человек и тот, к кому применяется речь разумного</span></div><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">غَيْرُ الْعَاقِلِ</span><span class="rule-term-ru">неразумный: предмет, животное и т.п.</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Используйте <span dir="rtl" lang="ar">هٰذَا</span>, когда указываете на один близкий объект мужского рода.</li><li>После <span dir="rtl" lang="ar">هٰذَا</span> ставится слово, которое объясняет, кто или что это.</li><li>В русском переводе отдельное слово «есть» обычно не нужно: <span dir="rtl" lang="ar">هٰذَا كِتَابٌ</span> — «Это книга».</li></ol></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры из шарха</span><div class="rule-example-list"><div class="rule-example-card rule-term-subject"><span class="rule-example-ar" dir="rtl" lang="ar">هٰذَا رَجُلٌ. هٰذَا وَلَدٌ. هٰذَا شَيْخٌ.</span><span class="rule-example-ru">Это мужчина. Это мальчик. Это шейх.</span></div><div class="rule-example-card rule-term-default"><span class="rule-example-ar" dir="rtl" lang="ar">هٰذَا كِتَابٌ. هٰذَا بَابٌ. هٰذَا قَلَمٌ.</span><span class="rule-example-ru">Это книга. Это дверь. Это ручка.</span></div></div></div><div class="rule-check-card"><b>Проверка по шарху:</b> соответствует первому разделу الدَّرْسُ الْأَوَّلُ: «هٰذَا: اسم إشارة للمفرد المذكر القريب، العاقل وغير العاقل».</div></div>$$,
  1,
  'rule',
  'هٰذَا اسم إشارة للمفرد المذكر القريب، للعاقل وغير العاقل.'
),
(
  'Мединский курс (Том 1)',
  '1',
  'مَا هٰذَا؟ (что это? — вопрос о неразумном)',
  $$<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">مَا هٰذَا؟</span><p class="rule-study-text"><span dir="rtl" lang="ar">مَا</span> — <span dir="rtl" lang="ar">اِسْمُ اِسْتِفْهَامٍ</span> для вопроса о <span dir="rtl" lang="ar">غَيْرُ الْعَاقِلِ</span>, то есть о предмете, животном и подобном.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">مَا</span><span class="rule-term-ru">что?</span></div><div class="rule-meaning-card rule-term-structure"><span class="rule-term-ar" dir="rtl" lang="ar">اِسْمُ اِسْتِفْهَامٍ</span><span class="rule-term-ru">вопросительное имя</span></div><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">غَيْرُ الْعَاقِلِ</span><span class="rule-term-ru">неразумный: предмет, животное и т.п.</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Если спрашиваем «что это?» о предмете, используем <span dir="rtl" lang="ar">مَا هٰذَا؟</span>.</li><li>Ответ строится через <span dir="rtl" lang="ar">هٰذَا</span>: <span dir="rtl" lang="ar">هٰذَا كِتَابٌ</span>.</li><li>Не используйте <span dir="rtl" lang="ar">مَا</span> для человека: для разумного будет <span dir="rtl" lang="ar">مَنْ</span>.</li></ol></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры из шарха</span><div class="rule-example-list"><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">مَا هٰذَا؟ هٰذَا كِتَابٌ. ✓</span><span class="rule-example-ru">Что это? Это книга.</span></div><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">مَا هٰذَا؟ هٰذَا بَابٌ. ✓</span><span class="rule-example-ru">Что это? Это дверь.</span></div><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">مَا هٰذَا؟ هٰذَا قَلَمٌ. ✓</span><span class="rule-example-ru">Что это? Это ручка.</span></div><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">مَا هٰذَا؟ هٰذَا رَجُلٌ. ✕</span><span class="rule-example-ru">Так не говорят о человеке в этом правиле.</span></div><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">مَا هٰذَا؟ هٰذَا وَلَدٌ. ✕</span><span class="rule-example-ru">Так не говорят о мальчике; нужен вопрос مَنْ.</span></div></div></div><div class="rule-check-card"><b>Проверка по шарху:</b> соответствует разделу «مَا هٰذَا؟»; правило ограничено вопросом о غير العاقل.</div></div>$$,
  2,
  'rule',
  'مَا اسم استفهام لغير العاقل: مَا هٰذَا؟ هٰذَا كِتَابٌ.'
),
(
  'Мединский курс (Том 1)',
  '1',
  'هَمْزَةُ الِاسْتِفْهَامِ: أَ، نَعَمْ، لَا (общий вопрос и ответы «да/нет»)',
  $$<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">أَ، نَعَمْ، لَا</span><p class="rule-study-text"><span dir="rtl" lang="ar">أَ</span> — <span dir="rtl" lang="ar">هَمْزَةُ الِاسْتِفْهَامِ</span>. Она ставится в начале фразы и делает общий вопрос. Ответом бывает <span dir="rtl" lang="ar">نَعَمْ</span> «да» или <span dir="rtl" lang="ar">لَا</span> «нет».</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">أَ</span><span class="rule-term-ru">вопросительная хамза</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">نَعَمْ</span><span class="rule-term-ru">да</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">لَا</span><span class="rule-term-ru">нет</span></div><div class="rule-meaning-card rule-term-structure"><span class="rule-term-ar" dir="rtl" lang="ar">حَرْفٌ</span><span class="rule-term-ru">частица</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Поставьте <span dir="rtl" lang="ar">أَ</span> перед утверждением: <span dir="rtl" lang="ar">هٰذَا سَرِيرٌ</span> → <span dir="rtl" lang="ar">أَهٰذَا سَرِيرٌ؟</span>.</li><li>Если утверждение верно, отвечайте <span dir="rtl" lang="ar">نَعَمْ</span>.</li><li>Если неверно, отвечайте <span dir="rtl" lang="ar">لَا</span> и затем дайте правильный ответ.</li></ol></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры из шарха</span><div class="rule-example-list"><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">أَهٰذَا سَرِيرٌ؟ نَعَمْ، هٰذَا سَرِيرٌ.</span><span class="rule-example-ru">Это кровать? Да, это кровать.</span></div><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">أَهٰذَا كُرْسِيٌّ؟ لَا، هٰذَا سَرِيرٌ.</span><span class="rule-example-ru">Это стул? Нет, это кровать.</span></div><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">أَهٰذَا رَجُلٌ؟ نَعَمْ، هٰذَا رَجُلٌ.</span><span class="rule-example-ru">Это мужчина? Да, это мужчина.</span></div><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">أَهٰذَا وَلَدٌ؟ لَا، هٰذَا رَجُلٌ.</span><span class="rule-example-ru">Это мальчик? Нет, это мужчина.</span></div><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">أَهٰذَا طَبِيبٌ؟ نَعَمْ، هٰذَا طَبِيبٌ. أَهٰذَا طَالِبٌ؟ لَا، هٰذَا طَبِيبٌ.</span><span class="rule-example-ru">Это врач? Да, это врач. Это студент? Нет, это врач.</span></div></div></div><div class="rule-check-card"><b>Проверка по шарху:</b> соответствует разделу «أَهٰذَا سَرِيرٌ؟» и примерам с نَعَمْ / لَا.</div></div>$$,
  3,
  'rule',
  'أَ همزة الاستفهام، وحرف جوابه نعم أو لا.'
),
(
  'Мединский курс (Том 1)',
  '1',
  'مَنْ هٰذَا؟ (кто это? — вопрос о разумном)',
  $$<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">مَنْ هٰذَا؟</span><p class="rule-study-text"><span dir="rtl" lang="ar">مَنْ</span> — <span dir="rtl" lang="ar">اِسْمُ اِسْتِفْهَامٍ</span> для вопроса о <span dir="rtl" lang="ar">الْعَاقِلِ</span>, то есть о разумном.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">مَنْ</span><span class="rule-term-ru">кто?</span></div><div class="rule-meaning-card rule-term-structure"><span class="rule-term-ar" dir="rtl" lang="ar">اِسْمُ اِسْتِفْهَامٍ</span><span class="rule-term-ru">вопросительное имя</span></div><div class="rule-meaning-card rule-term-subject"><span class="rule-term-ar" dir="rtl" lang="ar">الْعَاقِلُ</span><span class="rule-term-ru">разумный</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Если спрашиваем «кто это?» о человеке, используем <span dir="rtl" lang="ar">مَنْ هٰذَا؟</span>.</li><li>Ответ строится через <span dir="rtl" lang="ar">هٰذَا</span>: <span dir="rtl" lang="ar">هٰذَا طَبِيبٌ</span>.</li><li>Не используйте <span dir="rtl" lang="ar">مَنْ</span> для предмета: для неразумного будет <span dir="rtl" lang="ar">مَا</span>.</li></ol></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры из шарха</span><div class="rule-example-list"><div class="rule-example-card rule-term-subject"><span class="rule-example-ar" dir="rtl" lang="ar">مَنْ هٰذَا؟ هٰذَا طَبِيبٌ. ✓</span><span class="rule-example-ru">Кто это? Это врач.</span></div><div class="rule-example-card rule-term-subject"><span class="rule-example-ar" dir="rtl" lang="ar">مَنْ هٰذَا؟ هٰذَا وَلَدٌ. ✓</span><span class="rule-example-ru">Кто это? Это мальчик.</span></div><div class="rule-example-card rule-term-subject"><span class="rule-example-ar" dir="rtl" lang="ar">مَنْ هٰذَا؟ هٰذَا طَالِبٌ. ✓</span><span class="rule-example-ru">Кто это? Это студент.</span></div><div class="rule-example-card rule-term-subject"><span class="rule-example-ar" dir="rtl" lang="ar">مَنْ هٰذَا؟ هٰذَا كِتَابٌ. ✕</span><span class="rule-example-ru">Так не говорят о книге; нужен вопрос مَا.</span></div><div class="rule-example-card rule-term-subject"><span class="rule-example-ar" dir="rtl" lang="ar">مَنْ هٰذَا؟ هٰذَا قَلَمٌ. ✕</span><span class="rule-example-ru">Так не говорят о ручке; нужен вопрос مَا.</span></div></div></div><div class="rule-check-card"><b>Проверка по шарху:</b> соответствует разделу «مَنْ هٰذَا؟»; правило ограничено вопросом о العاقل.</div></div>$$,
  4,
  'rule',
  'مَنْ اسم استفهام للعاقل: مَنْ هٰذَا؟ هٰذَا طَبِيبٌ.'
);

commit;
